    bottom: -1px;
    height: 3px;
    background: var(--Accent, #3B82F6);
    border-radius: 2px;
}

/* ===========================
   Modal de Autenticación
=========================== */

#authOverlay[hidden] {
    display: none !important;
}

#authOverlay {
    position: fixed;
    inset: 0;
    display: grid;
    place-items: center;
    background: rgba(0, 0, 0, .35);
    z-index: 4000;
}

.auth-modal {
    position: relative;
    background: var(--ModuleBG, #fff);
    border-radius: var(--radius-12);
    padding: 24px;
    min-width: min(92vw, 420px);
    box-shadow: 0 20px 60px rgba(0, 0, 0, .35);
    font-family: var(--font-sans);
    color: var(--Text, #111827);
}

.auth-close {
    position: absolute;
    top: 12px;
    right: 12px;
    border: 0;
    background: none;
    font-size: 1rem;
    cursor: pointer;
    opacity: .7;
}

.auth-close:hover {
    opacity: 1;
}

.auth-modal .field {
    display: block;
    margin: 10px 0;
}

.auth-modal .field > span {
    display: block;
    font-size: var(--fs-small);
    margin-bottom: 6px;
    color: var(--Muted, #475569);
}

.auth-modal .req {
    color: var(--Danger, #ef4444);
    font-weight: var(--fw-bold, 700);
}

.auth-modal input {
    width: 100%;
    padding: 10px;
    border: 1px solid var(--LightText, #ddd);
    border-radius: 8px;
    font: inherit;
    color: var(--Text, #111827);
}

/* Espaciado ajustado para inputs en el formulario de login */
#loginForm input {
    margin-bottom: 12px;
}

#loginForm input:last-of-type {
    margin-bottom: 0;
}

/* Contenedor para el campo de contraseña con botón toggle */
.password-field {
    position: relative;
    display: flex;
    align-items: center;
}

.password-field input {
    width: 100%;
    padding-right: 75px !important; /* Más espacio para el ojo y la validación */
}

.toggle-password {
    position: absolute;
    right: 40px; /* Posición por defecto para formulario de registro */
    background: none;
    border: none;
    padding: 4px;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--Muted, #475569);
    transition: color 0.2s ease;
    z-index: 10;
}

/* Posición específica para el ojo en el formulario de login (más a la derecha) */
#loginForm .toggle-password {
    right: 10px;
}

#loginForm .password-field input {
    padding-right: 45px !important;
}

.toggle-password:hover {
    color: var(--Accent, #3B82F6);
}

.toggle-password:focus-visible {
    outline: 2px solid var(--Accent, #3B82F6);
    outline-offset: 2px;
    border-radius: 4px;
}

.auth-modal button[type="submit"] {
    width: 100%;
    margin-top: 10px;
    padding: 10px;
    border: 0;
    border-radius: var(--radius-10);
    background: var(--Accent, #3B82F6);
    color: #fff;
    font-weight: var(--fw-semibold, 600);
    cursor: pointer;
}

.auth-modal button[type="submit"]:hover {
    background: #2563EB;
}

.auth-modal .grid-2 {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 10px;
}

/* ===========================
   Responsive
=========================== */

@media (max-width: 768px) {
    .curated-toggle .toggle-label {
        display: none;
    }
}

@media (max-width: 560px) {
    .brand-name {
        font-size: var(--fs-h2);
    }

    .subnav a {
        font-size: var(--fs-small);
    }
}

// /static/js/auth.js
(function () {
  function $(id) { return document.getElementById(id); }

  // Refs del modal
  const overlay = $('authOverlay');
  const closeBtn = $('authClose');
  const loginPanel = $('loginPanel');
  const registerPanel = $('registerPanel');
  const toggleRegister = $('toggleRegister');
  const toggleLogin = $('toggleLogin');
  const loginForm = $('loginForm');
  const registerForm = $('registerForm');

  if (!overlay) return; // si no existe el modal, salgo

  // recordar el último trigger para devolver el foco al cerrar
  let lastTrigger = null;

  // Helpers
  function show(panel) {
    const isReg = panel === 'register';
    if (loginPanel) loginPanel.hidden = isReg;
    if (registerPanel) registerPanel.hidden = !isReg;

    // foco inicial en el primer input del panel visible
    const container = isReg ? registerPanel : loginPanel;
    const first = container && container.querySelector('input, select, textarea, button:not([type=button])');
    if (first) first.focus();
  }

  function openModal(panel = 'login', trigger = null) {
    lastTrigger = trigger || document.activeElement;
    overlay.hidden = false;
    document.body.classList.add('modal-open');
    overlay.setAttribute('aria-hidden', 'false');
    show(panel);
  }

  function closeModal() {
    overlay.hidden = true;
    document.body.classList.remove('modal-open');
    overlay.setAttribute('aria-hidden', 'true');
    // devolver foco al trigger
    if (lastTrigger && typeof lastTrigger.focus === 'function') {
      lastTrigger.focus();
    }
  }

  // Exponer para uso opcional desde otros scripts
  window.openAuthModal = openModal;

  // Delegación: abrir modal con data-auth="open"
  document.addEventListener('click', (e) => {
    const el = e.target.closest('[data-auth="open"]');
    if (!el) return;
    e.preventDefault();
    const panel = el.dataset.panel || 'login';
    openModal(panel, el); // NEW: pasar trigger
  });

  // Cerrar
  if (closeBtn) closeBtn.addEventListener('click', closeModal);
  overlay.addEventListener('click', (e) => { if (e.target === overlay) closeModal(); });
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && !overlay.hidden) closeModal();   // pequeño guard
  });

  // Toggle entre paneles dentro del modal
  if (toggleRegister) toggleRegister.addEventListener('click', (e) => { e.preventDefault(); show('register'); });
  if (toggleLogin)    toggleLogin.addEventListener('click',    (e) => { e.preventDefault(); show('login'); });

  // Submits fake login
  if (loginForm) loginForm.addEventListener('submit', (e) => {
    e.preventDefault();
    // validaciones nativas
    if (!loginForm.checkValidity && !loginForm.checkValidity?.()) {
      loginForm.reportValidity?.();
      return;
    }
    // TODO: hook a backend si lo necesitás
    closeModal();
  });

  // Submit registro: validación HTML5
  if (registerForm) registerForm.addEventListener('submit', (e) => {
    e.preventDefault();

    // limpiar espacios
    const first = registerForm.querySelector('#firstName');
    const last  = registerForm.querySelector('#lastName');
    [first, last].forEach(i => i && (i.value = i.value.trim()));

    if (!registerForm.checkValidity()) {
      registerForm.reportValidity();
      return;
    }

    // TODO: enviar al backend
    closeModal();
  });

})();

// /static/js/auth.js
(function () {
  function $(id) { return document.getElementById(id); }

  // Refs del modal
  const overlay = $('authOverlay');
  const closeBtn = $('authClose');
  const loginPanel = $('loginPanel');
  const registerPanel = $('registerPanel');
  const toggleRegister = $('toggleRegister');
  const toggleLogin = $('toggleLogin');
  const loginForm = $('loginForm');
  const registerForm = $('registerForm');

  if (!overlay) return; // si no existe el modal, salgo

  // recordar el último trigger para devolver el foco al cerrar
  let lastTrigger = null;

  // Helpers
  function show(panel) {
    const isReg = panel === 'register';
    if (loginPanel) loginPanel.hidden = isReg;
    if (registerPanel) registerPanel.hidden = !isReg;

    // foco inicial en el primer input del panel visible
    const container = isReg ? registerPanel : loginPanel;
    const first = container && container.querySelector('input, select, textarea, button:not([type=button])');
    if (first) first.focus();
  }

  function openModal(panel = 'login', trigger = null) {
    lastTrigger = trigger || document.activeElement;
    overlay.hidden = false;
    document.body.classList.add('modal-open');
    overlay.setAttribute('aria-hidden', 'false');
    show(panel);
  }

  function closeModal() {
    overlay.hidden = true;
    document.body.classList.remove('modal-open');
    overlay.setAttribute('aria-hidden', 'true');
    // devolver foco al trigger
    if (lastTrigger && typeof lastTrigger.focus === 'function') {
      lastTrigger.focus();
    }
  }

  // Exponer para uso opcional desde otros scripts
  window.openAuthModal = openModal;

  // Delegación: abrir modal con data-auth="open"
  document.addEventListener('click', (e) => {
    const el = e.target.closest('[data-auth="open"]');
    if (!el) return;
    e.preventDefault();
    const panel = el.dataset.panel || 'login';
    openModal(panel, el); // NEW: pasar trigger
  });

  // Cerrar
  if (closeBtn) closeBtn.addEventListener('click', closeModal);
  overlay.addEventListener('click', (e) => { if (e.target === overlay) closeModal(); });
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && !overlay.hidden) closeModal();   // pequeño guard
  });

  // Toggle entre paneles dentro del modal
  if (toggleRegister) toggleRegister.addEventListener('click', (e) => { e.preventDefault(); show('register'); });
  if (toggleLogin)    toggleLogin.addEventListener('click',    (e) => { e.preventDefault(); show('login'); });

  // Submits fake login
  if (loginForm) loginForm.addEventListener('submit', (e) => {
    e.preventDefault();
    // validaciones nativas
    if (!loginForm.checkValidity && !loginForm.checkValidity?.()) {
      loginForm.reportValidity?.();
      return;
    }
    // TODO: hook a backend si lo necesitás
    closeModal();
  });

  // Submit registro: validación HTML5
  if (registerForm) registerForm.addEventListener('submit', (e) => {
    e.preventDefault();

    // limpiar espacios
    const first = registerForm.querySelector('#firstName');
    const last  = registerForm.querySelector('#lastName');
    [first, last].forEach(i => i && (i.value = i.value.trim()));

    if (!registerForm.checkValidity()) {
      registerForm.reportValidity();
      return;
    }

    // TODO: enviar al backend
    closeModal();
  });

  // Toggle password visibility - manejo de clicks en los botones de ojo
  overlay.addEventListener('click', (e) => {
    const toggleBtn = e.target.closest('.toggle-password');
    if (!toggleBtn) return;

    e.preventDefault();
    e.stopPropagation();

    const targetId = toggleBtn.getAttribute('data-target');
    const passwordInput = document.getElementById(targetId);
    if (!passwordInput) return;

    const eyeIcon = toggleBtn.querySelector('.eye-icon');
    const eyeOffIcon = toggleBtn.querySelector('.eye-off-icon');

    if (passwordInput.type === 'password') {
      // Mostrar contraseña
      passwordInput.type = 'text';
      if (eyeIcon) eyeIcon.style.display = 'none';
      if (eyeOffIcon) eyeOffIcon.style.display = 'block';
      toggleBtn.setAttribute('aria-label', 'Ocultar contraseña');
    } else {
      // Ocultar contraseña
      passwordInput.type = 'password';
      if (eyeIcon) eyeIcon.style.display = 'block';
      if (eyeOffIcon) eyeOffIcon.style.display = 'none';
      toggleBtn.setAttribute('aria-label', 'Mostrar contraseña');
    }
  });

})();
